"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6357],{78738:a=>{a.exports=JSON.parse('{"slug":"semeynaya-ipoteka-oktyabr-2026-stavki","locale":"ru","title":"Семейная ипотека для семей с одним ребёнком подорожала с 6% до 10–12%","description":"С 1 октября 2026 года ставка по семейной ипотеке от 2% до 12% в зависимости от числа детей и региона. Как меняется платёж и кого это не коснётся.","blocks":[{"id":"b001","kind":"paragraph","text":"С 1 октября 2026 года ставка по программе \xabСемейная ипотека\xbb зависит от числа детей. Раньше она была 6% для всех. Теперь семья с одним ребёнком платит 10% в регионах и 12% в Москве, Петербурге, Московской и Ленинградской областях. С каждым следующим ребёнком ставка снижается на 2 пункта, до 2% в регионах и 4% в столицах при пяти детях."},{"id":"b002","kind":"paragraph","text":"Лимиты кредита по семейной ипотеке с 1 октября тоже зависят от числа детей. В регионах это 6 млн рублей для семьи с одним ребёнком, 8 млн с двумя и 10 млн с тремя и больше. В Москве, Петербурге и их областях 12, 15 и 18 млн рублей. Хотя бы одному ребёнку должно быть меньше 7 лет. Первоначальный взнос прежний, от 20%, его можно внести материнским капиталом."},{"id":"b003","kind":"paragraph","text":"Ставку не выше 6% при любом числе детей сохраняют в двух случаях: у семей с ребёнком-инвалидом и у тех, кто платит своими деньгами не меньше половины цены жилья или гасит долг до 50% в течение года после сделки. Новые условия касаются только договоров с 1 октября 2026 года. Тех, кто взял семейную ипотеку раньше, они не затрагивают."},{"id":"b004","kind":"paragraph","text":"Как устроена льгота. Банк выдаёт кредит под низкий процент, а разницу до рыночной ставки ему доплачивает государство. Это называют субсидированием ставки. Чем выше ключевая ставка Банка России, сейчас 14%, тем больше бюджет доплачивает за каждый льготный кредит. По новым правилам государство доплачивает только первые 15 лет кредита, а раньше доплачивало весь срок. После 15 лет ставка может вырасти до рыночной."},{"id":"b005","kind":"paragraph","text":"В рублях разница заметна. Ипотека на 6 млн рублей на 30 лет под 6% даёт платёж около 36 тыс. рублей в месяц. Под 10%, как теперь у семьи с одним ребёнком в регионе, тот же кредит в первые 15 лет стоит около 52,7 тыс. рублей в месяц, на 16,7 тыс. больше. Семье с тремя детьми в регионе ставка осталась 6%, а в Москве и Петербурге выросла до 8%. Льгота всё равно большая: полная стоимость обычной ипотеки в крупных банках 24 сентября 2026 года была около 22% годовых."},{"id":"b006","kind":"paragraph","text":"Чего пока не знаем: как новые правила скажутся на спросе и ценах в новостройках. Для семьи с одним ребёнком выбор такой. Брать кредит под 10–12% в расчёте на скорое рефинансирование значит ставить на снижение ключевой ставки, которое никто не обещал, следующее решение Банк России примет 23 октября. Откладывать покупку тоже стоит денег, потому что аренду всё это время надо платить. Взнос от половины цены возвращает ставку 6%, но забирает подушку безопасности."},{"id":"b007","kind":"heading","text":"Какая ставка по семейной ипотеке с 1 октября 2026 года?"},{"id":"b008","kind":"paragraph","text":"В регионах 10% для семьи с одним ребёнком, 8% с двумя, 6% с тремя, 4% с четырьмя и 2% с пятью и больше. В Москве, Петербурге и их областях ставки на 2 пункта выше, от 12% до 4%."},{"id":"b009","kind":"heading","text":"Изменится ли ставка по уже взятой семейной ипотеке?"},{"id":"b010","kind":"paragraph","text":"Нет. Новые условия касаются только договоров, заключённых с 1 октября 2026 года. По старым кредитам сохраняется прежняя ставка 6%."},{"id":"b011","kind":"heading","text":"Можно ли взять семейную ипотеку под 6% с одним ребёнком?"},{"id":"b012","kind":"paragraph","text":"Да, в двух случаях. Если в семье есть ребёнок-инвалид, или если семья платит своими деньгами не меньше половины цены жилья либо снижает долг до 50% в течение года после сделки."}],"sources":[{"label":"Семейную ипотеку привязали к количеству детей","url":"https://lenta.ru/news/2026/10/01/long-sem-ipo"},{"label":"Семейная ипотека с 1 октября 2026: новые ставки, лимиты и условия","url":"https://finance.mail.ru/article/semejnaya-ipoteka-po-novym-usloviyam-chto-menyaetsya-s-1-oktyabrya-69230142/"},{"label":"Семейная ипотека с 1 октября 2026 года: все новые условия","url":"https://bankinform.ru/news/143196"},{"label":"Условия по семейной ипотеке изменятся с 1 октября 2026 года","url":"https://rb.ru/news/usloviya-po-semejnoj-ipoteke-izmenyatsya-s-1-oktyabrya-2026-goda-stavka-budet-privyazana-k-kolichestvu-detej/"},{"label":"Семейная ипотека с 1 октября 2026: ставки и лимиты по числу детей","url":"https://finuslugi.ru/navigator/kak-ehto-rabotaet/stat_semeynaya-ipoteka-menyaetsya-s-1-iyulya"},{"label":"Стоимость ипотеки в сентябре 2026 года замерла","url":"https://brobank.ru/stoimost-ipoteki-sentyabr-2026-goda/"},{"label":"Банк России сохранил ключевую ставку на уровне 14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"910527a74fa7b29390aaa229e3ba15e4be6028a23c1921d265fdaa19884579bc"}')}}]);